function DeskForm({
  fields,
  initial,
  current,
  submitLabel,
  pending,
  error,
  onSubmit,
  onCancel
}: {
  fields: readonly DeskField[];
  initial: DeskValues;
  current?: Detail | null;
  submitLabel: string;
  pending: boolean;
  error: { message: string } | null;
  onSubmit: (values: DeskValues) => void;
  onCancel?: () => void;
}) {
  const [values, setValues] = useState<DeskValues>(initial);
  const [problem, setProblem] = useState<string | null>(null);
  const set: DeskSetter = (key, value) => setValues(current => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => {
    event.preventDefault();
    setProblem(null);
    try {
      onSubmit(values);
    } catch (err) {
      setProblem(err instanceof Error ? err.message : String(err));
    }
  };
  return (
    <form onSubmit={submit} className="grid max-w-xl gap-4">
      {fields.map(field => (
        <Fragment key={field}>{renderDeskField(field, values, set, current)}</Fragment>
      ))}
      <ErrorNote error={error ?? (problem ? { message: problem } : null)} />
      <div className="flex gap-2">
        <Button type="submit" disabled={pending}>
          {submitLabel}
        </Button>
        {onCancel ? (
          <Button type="button" variant="ghost" onClick={onCancel}>
            Cancel
          </Button>
        ) : null}
      </div>
    </form>
  );
}

