const BOARD_INPUT = { page: 1, page_size: PAGE_SIZE } as Inputs["posts"]["list"];
const COLUMNS = ["draft", "in_review", "approved", "retired"] as const;
type Column = (typeof COLUMNS)[number];

/** The transitions of Article: a card moves from one column to another only along one of these */
interface Move {
  name: string;
  from: readonly string[];
  to: Column;
  /** Whether the viewer's rule lets them run it on this card */
  allowed(user: SessionUser | null, row: Row): boolean;
  run(id: Row["id"]): Promise<unknown>;
}

const MOVES: Move[] = [
  {
    name: "submit",
    from: ["draft"],
    to: "in_review",
    allowed: (user, row) => user !== null && row.author_id === user.id,
    run: id => client.posts.submit({ id })
  },
  {
    name: "approve",
    from: ["in_review"],
    to: "approved",
    allowed: (user, row) => user !== null && (user as { role?: unknown }).role === "admin",
    run: id => client.posts.approve({ id })
  },
  {
    name: "reject",
    from: ["in_review"],
    to: "draft",
    allowed: (user, row) => user !== null && (user as { role?: unknown }).role === "admin",
    run: id => client.posts.reject({ id })
  },
  {
    name: "retire",
    from: ["approved"],
    to: "retired",
    allowed: (user, row) => (user !== null && (user as { role?: unknown }).role === "admin" || (user !== null && row.author_id === user.id && String(row.status) === "approved")),
    run: id => client.posts.retire({ id })
  }
];

/** The transition that takes a card to a column from where it is, if the viewer may run one */
function moveTo(user: SessionUser | null, row: Row, column: Column): Move | undefined {
  return MOVES.find(move => move.to === column && move.from.includes(String(row.status)) && move.allowed(user, row));
}

function DeskIndexInner() {
  const [archived, setArchived] = useState(false);
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  const boardInput = { ...BOARD_INPUT, ...(archived ? { archived: "true" as const } : {}) } as Inputs["posts"]["list"];
  const boardKey = [...KEY, "list", boardInput] as const;
  const list = useQuery({ queryKey: boardKey, queryFn: () => client.posts.list(boardInput) });
  const [openAction, setOpenAction] = useState<string | null>(null);
  void openAction;
  void setOpenAction;
  // The card in the air, the column that last refused it, and what the board says about a drop it did not take
  const [dragging, setDragging] = useState<Row | null>(null);
  const refusedBy = useRef<Column | null>(null);
  const [refusal, setRefusal] = useState<string | null>(null);
  const router = useRouter();
  const queryClient = useQueryClient();
  const unpublish_allAction = useMutation({
    mutationFn: (input: Inputs["posts"]["unpublish_all"]) => client.posts.unpublish_all(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  const move = useMutation({
    mutationFn: ({ id, step }: { id: Row["id"]; step: Move }) => step.run(id),
    onMutate: async ({ id, step }) => {
      await queryClient.cancelQueries({ queryKey: boardKey });
      const previous = queryClient.getQueryData<Outputs["posts"]["list"]>(boardKey);
      if (previous) {
        queryClient.setQueryData<Outputs["posts"]["list"]>(boardKey, {
          ...previous,
          data: previous.data.map(row => (row.id === id ? { ...row, status: step.to } : row))
        });
      }
      return { previous };
    },
    onError: (_error, _input, context) => {
      if (context?.previous) queryClient.setQueryData(boardKey, context.previous);
    },
    onSettled: () => queryClient.invalidateQueries({ queryKey: KEY })
  });
  const rows = list.data?.data ?? [];
  return (
    <div
      className="flex h-full min-h-0 flex-col"
      onDragOverCapture={() => {
        refusedBy.current = null;
      }}
    >
      <PaneHeader title="Editorial desk" count={list.data?.page.total}>
          <Button
            variant={archived ? "secondary" : "ghost"}
            size="sm"
            aria-pressed={archived}
            onClick={() => {
              setArchived(current => !current);
            }}
          >
            {archived ? "Showing archived" : "Show archived"}
          </Button>
          {canCreate(user) ? (
            <Link href="/desk/new" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="New article">
              <Plus />
            </Link>
          ) : null}
          {canUnpublishAll(user) ? (
            <Button variant="outline" size="sm" disabled={unpublish_allAction.isPending} onClick={() => unpublish_allAction.mutate({})}>
              Unpublish All
            </Button>
          ) : null}
      </PaneHeader>

        <ErrorNote error={unpublish_allAction.error} className="m-4" />
      <ErrorNote error={move.error ?? list.error} className="m-4" />
      {refusal ? (
        <p role="status" data-board-refusal className="mx-4 mt-4 rounded-md border border-border bg-muted/40 px-3 py-2 text-sm text-muted-foreground">
          {refusal}
        </p>
      ) : null}
      {list.isPending ? (
        <ListSkeleton />
      ) : (
        <div className="flex min-h-0 flex-1 gap-4 overflow-x-auto p-4">
          {COLUMNS.map(column => {
            const offered = dragging && dragging.status !== column ? Boolean(moveTo(user, dragging, column)) : null;
            return (
              <section
                key={column}
                data-column={column}
                data-offered={offered === null ? undefined : offered}
                className={cn(
                  "flex w-72 shrink-0 flex-col rounded-lg border border-border bg-muted/30",
                  offered === true && "ring-2 ring-ring",
                  offered === false && "opacity-50"
                )}
                onDragOver={event => {
                  if (!dragging || dragging.status === column) return;
                  // Only a column a transition reaches takes the drop; over any other the browser shows no-drop
                  if (moveTo(user, dragging, column)) event.preventDefault();
                  else refusedBy.current = column;
                }}
                onDrop={event => {
                  event.preventDefault();
                  const step = dragging ? moveTo(user, dragging, column) : undefined;
                  if (dragging && step) move.mutate({ id: dragging.id, step });
                  setDragging(null);
                }}
              >
                <header className="flex items-center justify-between px-3 py-2 text-sm font-medium">
                  <span>{column}</span>
                  <span className="text-xs text-muted-foreground">{rows.filter(r => r.status === column).length}</span>
                </header>
                <div className="flex min-h-0 flex-1 flex-col gap-2 overflow-y-auto p-2">
                  {rows
                    .filter(r => r.status === column)
                    .map((row: Row) => (
                      <div
                        key={text(row.id)}
                        data-card={text(row.id)}
                        draggable
                        onDragStart={event => {
                          event.dataTransfer.setData("text/plain", text(row.id));
                          event.dataTransfer.effectAllowed = "move";
                          refusedBy.current = null;
                          setRefusal(null);
                          setDragging(row);
                        }}
                        onDragEnd={() => {
                          // Let go over a column no transition reaches: the card never left, and the board says why
                          if (refusedBy.current)
                            setRefusal(`No transition takes a card from ${row.status} to ${refusedBy.current}.`);
                          refusedBy.current = null;
                          setDragging(null);
                        }}
                        onClick={() => router.push(`/desk/${text(row.id)}`)}
                        className="cursor-grab rounded-md border border-border bg-card p-3 text-sm shadow-xs hover:bg-accent/40 active:cursor-grabbing"
                      >
                        <div className="font-medium">{text(row.title) || text(row.id)}</div>
                        <div className="mt-1 text-xs text-muted-foreground">{[(row.author ? text(row.author.name) : text(row.author_id))].filter(Boolean).join(" · ")}</div>
                      </div>
                    ))}
                </div>
              </section>
            );
          })}
        </div>
      )}
    </div>
  );
}

function DeskNewInner() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.posts.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push(`/desk/${text(row.id)}`);
    }
  });
  // A field with a read rule is offered only to a viewer who could read it, and is not sent otherwise
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const could: Record<string, boolean> = fieldsOf(session.data).posts;
  const readable = (field: string) => could[field] === true;
  return (
    <Pane title="New article" actions={<Link href="/desk" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>}>
      <DeskForm
        fields={offeredDesk(DESK_CREATE, readable)}
        initial={EMPTY_DESK}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(sentDesk(toDeskCreateInput(values), readable))}
      />
    </Pane>
  );
}

